# Upper bound per class after expansion — see the capping note in
# build_augmented() for why this matters.
MAX_PER_CLASS = 110

# Slot values sampled per template. The full cross-product buried the
# paraphrase examples under near-duplicate noun swaps.
SLOTS_PER_TEMPLATE = 6

FILLER_PREFIX = ["", "", "", "", "umm ", "uh ", "ok ", "hey ", "so ", "can you ", "please "]
FILLER_SUFFIX = ["", "", "", "", "", " please", " for me", " now", " thanks"]


def _noisy(text: str, rng: random.Random) -> str:
    """Add the filler that real STT output carries."""
    return (rng.choice(FILLER_PREFIX) + text + rng.choice(FILLER_SUFFIX)).strip()


def _load_feedback() -> dict[str, list[str]]:
    """Real logged utterances, written by training/collect_feedback.py.

    Absent on a fresh install; that is the normal case and not an error.
    """
    import json
    from pathlib import Path

    path = Path(__file__).parent.parent / "data" / "models" / "feedback_data.json"
    if not path.exists():
        return {}
    try:
        with open(path) as f:
            data = json.load(f)
        if isinstance(data, dict):
            return {k: list(v) for k, v in data.items() if isinstance(v, list)}
    except Exception:
        pass
    return {}


def build_augmented() -> dict[str, list[str]]:
    """Handwritten data + template expansion + filler noise."""
    from ai.intent_dataset import TRAINING_DATA

    rng = random.Random(1337)
    out: dict[str, list[str]] = {k: list(v) for k, v in TRAINING_DATA.items()}

    # Extra handwritten
    for skill, extra in EXTRA.items():
        out.setdefault(skill, []).extend(extra)

    # Paraphrase bank — verb/structure diversity. This is what the holdout
    # evaluation showed was missing: the model knew many app NAMES but only a
    # few ways to ASK. See ai/intent_paraphrases.py.
    from ai.intent_paraphrases import PARAPHRASES
    for skill, phrases in PARAPHRASES.items():
        out.setdefault(skill, []).extend(phrases)

    # Template expansion, sampled.
    #
    # Previously every template was crossed with every slot value, which gave
    # open_app 8 templates x 36 apps = 288 near-identical examples and taught
    # the model nouns instead of verbs. Sampling a handful of slot values per
    # template keeps the pattern represented without swamping the paraphrases.
    for skill, templates in TEMPLATES.items():
        bucket = out.setdefault(skill, [])
        for tmpl, slots in templates:
            picks = rng.sample(slots, k=min(SLOTS_PER_TEMPLATE, len(slots)))
            for value in picks:
                bucket.append(tmpl.format(value))

    # Filler noise on a sampled third — enough to teach robustness without
    # drowning the clean forms.
    for skill, utts in out.items():
        sample = rng.sample(utts, k=max(1, len(utts) // 3))
        utts.extend(_noisy(u, rng) for u in sample)

    # De-duplicate, preserving order.
    for skill in out:
        seen: set[str] = set()
        deduped = []
        for u in out[skill]:
            key = u.strip().lower()
            if key and key not in seen:
                seen.add(key)
                deduped.append(key)
        out[skill] = deduped

    # Real usage, if any has been collected.
    #
    # Loaded LAST and exempt from the cap below, because these are the most
    # valuable examples in the set: actual phrasings from actual use, rather
    # than anything I guessed. See training/collect_feedback.py.
    feedback = _load_feedback()
    for skill, utts in feedback.items():
        out.setdefault(skill, []).extend(u.strip().lower() for u in utts)

    # Cap over-expanded classes.
    #
    # Slot expansion is generous for skills with big vocabularies: open_app
    # reached 367 examples while restart_system had 13, a 28:1 imbalance.
    # Class weighting alone does not fully compensate at that ratio — the
    # decision boundary still drifts toward the crowded classes. Capping
    # keeps template coverage broad without letting three skills dominate
    # the loss. Handwritten examples are kept preferentially since they are
    # the most natural; templated ones are sampled to fill the remainder.
    for skill, utts in out.items():
        if len(utts) <= MAX_PER_CLASS:
            continue
        # Real usage and handwritten examples are protected from capping;
        # only templated filler gets sampled away.
        handwritten = set(
            u.strip().lower() for u in TRAINING_DATA.get(skill, [])
        ) | set(u.strip().lower() for u in EXTRA.get(skill, [])) | set(
            u.strip().lower() for u in feedback.get(skill, [])
        )
        keep = [u for u in utts if u in handwritten]
        rest = [u for u in utts if u not in handwritten]
        rng.shuffle(rest)
        out[skill] = (keep + rest)[:MAX_PER_CLASS]

    return out


def flatten_augmented() -> tuple[list[str], list[str]]:
    data = build_augmented()
    texts: list[str] = []
    labels: list[str] = []
    for skill, utts in data.items():
        for u in utts:
            texts.append(u)
            labels.append(skill)
    return texts, labels


if __name__ == "__main__":
    data = build_augmented()
    total = sum(len(v) for v in data.values())
    print("Augmented intent dataset:")
    for skill, utts in sorted(data.items(), key=lambda kv: -len(kv[1])):
        print(f"  {skill:20} {len(utts):4}")
    print(f"  {'TOTAL':20} {total:4} across {len(data)} classes")
    print(f"  mean per class: {total / len(data):.0f}")
